%root_path = fileparts(mfilename("fullpath"));
%root_path = pwd;

% retrieve selected cuts used for further fitting
[HN_FFCutsFits,CutFitFileHN] = recover_selected_cuts('HN_FFCutsFits','e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts');

%%
fn = fieldnames(HN_FFCutsFits);
nf = 11 %[output:888861f2]
%for i = 11:numel(fn)
%selectCuts = fn{nf};
selectCuts = 'Ei800_off1H1H0_HNminFF' %[output:3b59efcf]
if ismember(selectCuts(1:3),{'msk','dat'})||...
        contains(selectCuts,'all_fit_par')
    %continue
    error('Can not fit field: %s',selectCuts);
end

fprintf('ProcessiHN cuts: %s \n', selectCuts); %[output:1fa9b020]
cuts_list = HN_FFCutsFits.(selectCuts);
if ~iscell(cuts_list)
    cuts_list = {cuts_list};
end
if contains(selectCuts,'Ei200')
    min_Ei = 30;        
    mi = maps_instrument(200,600,'S');
end
if contains(selectCuts,'Ei400')
    min_Ei = 40;            
    mi = maps_instrument(401,600,'S');
end
if contains(selectCuts,'Ei800')
    min_Ei = 70;            
    mi = maps_instrument(786,600,'S');
end
sample=IX_sample(true,[1,0,0],[0,1,0],'cuboid',[0.04,0.03,0.02]);
for j=1:numel(cuts_list) %[output:group:5a4ea1ee]
    cuts_list{j} = cuts_list{j}.set_instrument(mi);
    cuts_list{j} = cuts_list{j}.set_sample(sample);
    plot(cuts_list{j}); lz 0 0.3; keep_figure; %[output:69eba797]
end %[output:group:5a4ea1ee]
dir_name  = "HN";

dE_step = 2; %original energy transfer step data were binned to. No point in going finer
half_dE = 5; % half width of data binning

en_mm = cuts_list{1}.data.img_range(:,4);
en_mm(1) = max(min_Ei,en_mm(1));
en_mm(1) = 200;
%en_mm(2) = 380;
cut_en = en_mm(1)+half_dE:2*half_dE:(en_mm(2)-half_dE);

cut_dimensions = 1;
HN_FFCutsFits.(selectCuts) = cuts_list;
%%
HN_FFCutsFits = fit_cut2JFF_along_direction(... %[output:group:35690fa8] %[output:8f255e44] %[output:0774448a] %[output:461a08b0] %[output:68b6deea] %[output:578b43fd] %[output:61df9c42] %[output:3ac51e1b] %[output:7271c8a2] %[output:7dc03f46] %[output:2c09787e] %[output:5a4ee79c] %[output:52c1612e] %[output:8c400990] %[output:00634716] %[output:0534d59d] %[output:1c3e24f3] %[output:1e893c4f] %[output:554697ab] %[output:79f77afc] %[output:5f6a919c] %[output:0d155fa8] %[output:6f60d37d] %[output:4f692d59] %[output:5cfcf16b] %[output:4bb3f52f] %[output:0bbd0514] %[output:481a68ad] %[output:60ce4fc4] %[output:3fcfe090] %[output:630838ae] %[output:42a02918] %[output:7374128e] %[output:73825135] %[output:5b266a97] %[output:7e955bde] %[output:1746f5f3] %[output:5f154e34] %[output:4315be6a] %[output:21921a76] %[output:50b18f90] %[output:450b06f4] %[output:6e6a422c] %[output:8fbf83a6] %[output:627c9d59] %[output:5835be66] %[output:6f94f4c5] %[output:1fa8bfb5] %[output:4a03e6bd] %[output:104d0c31] %[output:01ecc195] %[output:1b1a4cdb]
    HN_FFCutsFits,selectCuts,cut_dimensions,cut_en,dE_step,half_dE,true); %[output:group:35690fa8] %[output:8f255e44] %[output:0774448a] %[output:461a08b0] %[output:68b6deea] %[output:578b43fd] %[output:61df9c42] %[output:3ac51e1b] %[output:7271c8a2] %[output:7dc03f46] %[output:2c09787e] %[output:5a4ee79c] %[output:52c1612e] %[output:8c400990] %[output:00634716] %[output:0534d59d] %[output:1c3e24f3] %[output:1e893c4f] %[output:554697ab] %[output:79f77afc] %[output:5f6a919c] %[output:0d155fa8] %[output:6f60d37d] %[output:4f692d59] %[output:5cfcf16b] %[output:4bb3f52f] %[output:0bbd0514] %[output:481a68ad] %[output:60ce4fc4] %[output:3fcfe090] %[output:630838ae] %[output:42a02918] %[output:7374128e] %[output:73825135] %[output:5b266a97] %[output:7e955bde] %[output:1746f5f3] %[output:5f154e34] %[output:4315be6a] %[output:21921a76] %[output:50b18f90] %[output:450b06f4] %[output:6e6a422c] %[output:8fbf83a6] %[output:627c9d59] %[output:5835be66] %[output:6f94f4c5] %[output:1fa8bfb5] %[output:4a03e6bd] %[output:104d0c31] %[output:01ecc195] %[output:1b1a4cdb]
cl = HN_FFCutsFits.(selectCuts);
if iscell(cl)
    HN_FFCutsFits.(selectCuts) = [cl{:}];
end

beep
beep
beep
%%

all_fit_par = HN_FFCutsFits.([selectCuts,'_2Jng_fit_par']);
bg_data = extract_bg_par(all_fit_par,[1,2]);
% original slope parameters
pd(bg_data(1));lx(all_fit_par(1).en,all_fit_par(end).en);ly 0 0.05; keep_figure; %[output:445a8e9e]
pd(bg_data(2));lx(all_fit_par(1).en,all_fit_par(end).en);keep_figure %[output:0ef0ca80]
%pd(bg_data(3));lx(fit_res.peak_fit_par(1).en,fit_res.peak_fit_par(end).en);keep_figure;
%pd(bg_data(4));lx(fit_res.peak_fit_par(1).en,fit_res.peak_fit_par(end).en);keep_figure
%%

doc = matlab.desktop.editor.getActive;
doc.save;
thisFile = 'e:\SHARE\Fe\Data\analysis\06_fit_with_AQ0\fit_cutFe_HN.m';
targ_file = fullfile(fileparts(thisFile),['fit_cutFe_HN_',selectCuts,'.pdf']);
export(thisFile,targ_file);
%close all;
%end
%%
J0 = extract_fit_par(all_fit_par,6,'J0','meV');
J1 = extract_fit_par(all_fit_par,7,'J1','meV');
acolor k; pd(J0); %[output:8d441b45]
acolor g; pd(J1);ly 10 500;keep_figure; %[output:8d441b45]
%%
fit_src_struc = HN_FFCutsFits;
save(CutFitFileHN,"fit_src_struc",'-v7.3')

